import asyncio, json
from common import *
C = "window._n.spll"
async def ev(pg, js): return await pg.evaluate(f"() => {{ const c = {C}; return {js}; }}")
CANVAS = (1180, 520)
async def canvas_click(pg, dx=0):
    await pg.mouse.click(CANVAS[0]+dx, CANVAS[1]+dx); await pg.wait_for_timeout(250)
def grp(name): return f".spll-tree .spll-group:has(.spll-gname:text-is('{name}'))"
async def main():
    logs=[]
    async with async_playwright() as p:
        b, pg = await open_page(p, logs)
        await pg.evaluate(SETUP); await pg.wait_for_timeout(1500)
        await choose_root(pg); await pg.wait_for_timeout(1500)
        print("0 label:", await pg.locator(".spll-root-label").inner_text(), "| title tools:", await pg.locator(".spll-title-tool").count())
        print("  top-level order:", await pg.locator(".spll-tree .spll-group .spll-gname").all_inner_texts())
        # 1. menus
        await pg.click(grp("styles") + " [data-act=gmenu]"); await pg.wait_for_timeout(200)
        print("1 menu open:", await ev(pg, "c.overlay?.kind"))
        await canvas_click(pg)
        print("  after canvas click:", await ev(pg, "c.overlay?.kind ?? null"))
        await pg.click(grp("styles") + " [data-act=gmenu]"); await pg.wait_for_timeout(200)
        await pg.screenshot(path=OUT+"89_menu.png", clip={"x":300,"y":60,"width":440,"height":620})
        print("  pop at:", await pg.locator(".spll-pop").bounding_box(), "btn at:", await pg.locator(grp("styles") + " [data-act=gmenu]").bounding_box(), await ev(pg, "JSON.stringify(c.overlay && {x:c.overlay.x,y:c.overlay.y,a:c.overlay.alignRight})"))
        await pg.click(grp("styles") + " [data-act=gmenu]", timeout=3000); await pg.wait_for_timeout(200)
        print("  ⋯ pressed twice:", await ev(pg, "c.overlay?.kind ?? null"))
        await pg.click(".spll-strip .spll-gear"); await pg.wait_for_timeout(200)
        print("  gear:", await ev(pg, "c.overlay?.kind ?? null"))
        await pg.click(".spll-strip .spll-gear"); await pg.wait_for_timeout(200)
        print("  gear again:", await ev(pg, "c.overlay?.kind ?? null"))
        # rename prompt stays open on canvas click, closes on node click
        await pg.click(grp("styles") + " [data-act=gmenu]"); await pg.click(".spll-menu-item:text-is('Rename…')"); await pg.wait_for_timeout(200)
        await pg.keyboard.type("half"); await canvas_click(pg, 20)
        print("  rename after canvas click:", await ev(pg, "c.overlay?.kind ?? null"), "| typed kept:", await pg.locator(".spll-pop-input").input_value())
        await pg.click(".spll-active-list"); await pg.wait_for_timeout(200)
        print("  rename after node click:", await ev(pg, "c.overlay?.kind ?? null"))
        # 2. settings tabs
        await pg.click(".spll-strip .spll-gear"); await pg.wait_for_timeout(200)
        print("2 tabs:", await pg.locator(".spll-tab").all_inner_texts(), "| on:", await pg.locator(".spll-tab.is-on").inner_text())
        await pg.click(".spll-tab:text-is('Lists')"); await pg.wait_for_timeout(150)
        print("  lists labels:", await pg.locator(".spll-settings-body .spll-label").all_inner_texts())
        await pg.screenshot(path=OUT+"90_settings.png", clip={"x":300,"y":60,"width":440,"height":620})
        await pg.evaluate("() => { const n = window._n; n.setSize([n.size[0], 330]); n.setDirtyCanvas(true,true); }"); await pg.wait_for_timeout(400)
        await pg.click(".spll-tab:text-is('Display')"); await pg.wait_for_timeout(150)
        await pg.evaluate("() => { const b = document.querySelector('.spll-settings-body'); b.scrollTop = 9999; }"); await pg.wait_for_timeout(100)
        xb = await pg.locator(".spll-settings .spll-sheet-title [data-act=close]").bounding_box()
        sb = await pg.locator(".spll-settings").bounding_box()
        print("  small node: × visible:", xb is not None and xb["y"] >= sb["y"] - 1, "| body scrolls:", await pg.evaluate("() => { const b = document.querySelector('.spll-settings-body'); return b.scrollHeight > b.clientHeight && b.scrollTop > 0; }"))
        await pg.screenshot(path=OUT+"91_settings_small.png", clip={"x":300,"y":60,"width":440,"height":420})
        await pg.click(".spll-settings .spll-sheet-title [data-act=close]"); await pg.wait_for_timeout(200)
        await pg.evaluate("() => { const n = window._n; n.setSize([n.size[0], 640]); n.setDirtyCanvas(true,true); }"); await pg.wait_for_timeout(400)
        await pg.click(".spll-strip .spll-gear"); await pg.wait_for_timeout(200)
        print("  remembers tab:", await pg.locator(".spll-tab.is-on").inner_text())
        await canvas_click(pg)
        print("  settings closed by canvas click:", await ev(pg, "c.overlay?.kind ?? null"))
        # 3. expand / collapse all, select mode
        await pg.click("[data-act=expand-all]"); await pg.wait_for_timeout(200)
        print("3 expand all -> collapsed:", await ev(pg, "c.state.groups.filter(g => g.collapsed).length"), "of", await ev(pg, "c.state.groups.length"))
        await pg.click("[data-act=collapse-all]"); await pg.wait_for_timeout(200)
        print("  collapse all -> collapsed:", await ev(pg, "c.state.groups.filter(g => g.collapsed).length"))
        await pg.click("[data-act=select-groups]"); await pg.wait_for_timeout(200)
        print("  select: bar:", (await pg.locator(".spll-tree-title").inner_text()).replace("\n"," "), "| rows:", await pg.locator(".spll-sel-row").count())
        await pg.screenshot(path=OUT+"92_select.png", clip={"x":300,"y":60,"width":440,"height":620})
        await pg.click(".spll-sel-row:has(.spll-gname:text-is('styles')) .spll-sel-inside"); await pg.wait_for_timeout(150)
        print("  all inside on styles ->", await pg.locator(".spll-sel-count").inner_text())
        await pg.click(".spll-sel-row:has(.spll-gname:text-is('anime'))"); await pg.wait_for_timeout(150)
        print("  tick anime (parent styles ticked too):", await ev(pg, "[...c.selectMode.ticks].map(id => c.m.byId.get(id)?.name || id).sort()").__await__() if False else await ev(pg, "['styles','anime'].map(n => c.selectMode.ticks.has(c.state.groups.find(g => g.name === n).id))"))
        await pg.click("[data-act=sel-invert]"); await pg.wait_for_timeout(150)
        print("  invert ->", await pg.locator(".spll-sel-count").inner_text())
        await pg.click("[data-act=sel-invert]"); await pg.wait_for_timeout(150)
        await pg.click("[data-act=sel-apply]"); await pg.wait_for_timeout(300)
        st = await ev(pg, "Object.fromEntries(c.state.groups.map(g => [g.name, !g.collapsed]))")
        print("  applied open:", {k:v for k,v in st.items() if v}, "| select mode off:", await ev(pg, "!c.selectMode"))
        await pg.click("[data-act=select-groups]"); await pg.wait_for_timeout(150); await pg.click("[data-act=sel-all]"); await pg.wait_for_timeout(100)
        print("  untick all ->", await pg.locator(".spll-sel-count").inner_text(), "| button now:", await pg.locator("[data-act=sel-all]").inner_text())
        await pg.keyboard.press("Escape"); await pg.wait_for_timeout(150)
        print("  escape cancels:", await ev(pg, "!c.selectMode"), "| unchanged:", await ev(pg, "Object.fromEntries(c.state.groups.map(g => [g.name, !g.collapsed]))") == st)
        # 4. ordering
        await pg.evaluate("() => { const c = window._n.spll; c.commit(s => { for (const g of s.groups) g.collapsed = !['styles','anime','painterly'].includes(g.name); }); }"); await pg.wait_for_timeout(200)
        print("4 anime order:", await pg.locator(".spll-box[data-box] .spll-lora .spll-name").all_inner_texts())
        src = pg.locator(".spll-tree .spll-lora:has(.spll-name:text-is('anime_soft'))"); dst = pg.locator(".spll-tree .spll-lora:has(.spll-name:text-is('anime_bold'))")
        sb_ = await src.locator(".spll-name").bounding_box(); db_ = await dst.bounding_box()
        await pg.mouse.move(sb_["x"]+10, sb_["y"]+8); await pg.mouse.down(); await pg.wait_for_timeout(450)
        await pg.mouse.move(db_["x"]+60, db_["y"]+4, steps=6); await pg.wait_for_timeout(200)
        await pg.mouse.up(); await pg.wait_for_timeout(500)
        print("  after drag:", await pg.locator(".spll-box[data-box] .spll-lora .spll-name").all_inner_texts(), "| dialog:", await pg.locator("[role=dialog]:not(.spll-modal)").count(), "| order saved:", await ev(pg, "Object.keys(c.state.order)"))
        await pg.click(grp("anime") + " [data-act=gmenu]"); await pg.click(".spll-menu-item:text-is('Sort…')"); await pg.wait_for_timeout(200)
        print("  sort popup:", [x.replace("\n"," ") for x in await pg.locator(".spll-sort-opt").all_inner_texts()])
        await pg.screenshot(path=OUT+"93_sort.png", clip={"x":300,"y":60,"width":440,"height":620})
        await pg.click(".spll-sort-opt[data-mode=za]"); await pg.wait_for_timeout(200)
        print("  Z to A:", await pg.locator(".spll-box[data-box] .spll-lora .spll-name").all_inner_texts())
        await pg.click(grp("anime") + " [data-act=gmenu]"); await pg.click(".spll-menu-item:text-is('Sort…')"); await pg.click(".spll-sort-opt[data-mode=strict]"); await pg.wait_for_timeout(200)
        print("  strict A to Z:", await pg.locator(".spll-box[data-box] .spll-lora .spll-name").all_inner_texts(), "| order left:", await ev(pg, "Object.keys(c.state.order)"))
        # group reorder: drag 'painterly' above 'anime' (top edge)
        gs = pg.locator(grp("painterly") + " .spll-gname"); gd = pg.locator(grp("anime"))
        a = await gs.bounding_box(); t = await gd.bounding_box()
        await pg.mouse.move(a["x"]+5, a["y"]+6); await pg.mouse.down(); await pg.wait_for_timeout(450)
        await pg.mouse.move(t["x"]+80, t["y"]+3, steps=6); await pg.wait_for_timeout(200); await pg.mouse.up(); await pg.wait_for_timeout(500)
        print("  styles children after group drag:", await ev(pg, "(c.m.childGroups.get(c.state.groups.find(g=>g.name==='styles').id) || []).map(g => g.name)"), "| dialog:", await pg.locator("[role=dialog]:not(.spll-modal)").count())
        # 5. ENABLED reorder without confirm
        await pg.evaluate("() => { const c = window._n.spll; [...c.files.keys()].slice(0,3).forEach(k => c.setActive(k, true)); }"); await pg.wait_for_timeout(300)
        before = await pg.locator(".spll-active-list .spll-lora .spll-name").all_inner_texts()
        r1 = await pg.locator(".spll-active-list .spll-lora").nth(2).locator(".spll-name").bounding_box(); r0 = await pg.locator(".spll-active-list .spll-lora").nth(0).bounding_box()
        await pg.mouse.move(r1["x"]+5, r1["y"]+8); await pg.mouse.down(); await pg.wait_for_timeout(450)
        await pg.mouse.move(r0["x"]+60, r0["y"]+3, steps=6); await pg.wait_for_timeout(200); await pg.mouse.up(); await pg.wait_for_timeout(500)
        print("5 ENABLED:", before, "->", await pg.locator(".spll-active-list .spll-lora .spll-name").all_inner_texts(), "| dialog:", await pg.locator("[role=dialog]:not(.spll-modal)").count())
        # 6. favourites rows
        await pg.evaluate("() => { const c = window._n.spll; const ks = [...c.files.keys()]; c.toggleFav(ks[0]); c.toggleFav(ks[5]); }"); await pg.wait_for_timeout(200)
        await pg.click(".spll-active-list", button="right"); await pg.hover(".spll-pmenu-item:has-text('Favourites')"); await pg.wait_for_timeout(400)
        print("6 fav rows on:", await pg.locator(".spll-pmenu-sub .spll-pmenu-lora.is-on").count(), "of", await pg.locator(".spll-pmenu-sub .spll-pmenu-lora").count())
        await pg.screenshot(path=OUT+"94_favs.png")
        off = pg.locator(".spll-pmenu-sub .spll-pmenu-lora:not(.is-on) .spll-result-name").first
        name = await off.inner_text(); await off.click(); await pg.wait_for_timeout(250)
        print("  clicked", name, "-> on:", await pg.locator(".spll-pmenu-sub .spll-pmenu-lora.is-on").count(), "| menu still open:", await pg.locator(".spll-pmenu-sub").count())
        await pg.locator(".spll-pmenu-sub .spll-pmenu-lora.is-on .spll-result-name").first.click(); await pg.wait_for_timeout(250)
        print("  clicked an on row -> on:", await pg.locator(".spll-pmenu-sub .spll-pmenu-lora.is-on").count())
        await pg.locator(".spll-pmenu-sub .spll-pmenu-lora").first.click(button="right"); await pg.wait_for_timeout(200); await pg.locator(".spll-pmenu").last.locator(".spll-pmenu-item:has-text('Show in groups')").click(); await pg.wait_for_timeout(400)
        print("  ⌖ -> menu closed:", await pg.locator(".spll-pmenu-sub").count() == 0, "| flashing in tree:", await pg.locator(".spll-tree .is-flash").count())
        print("ERRORS", errs(logs)[:6])
        await b.close()
asyncio.run(main())
